// Filename/folder -> icon id, Material Icon Theme style (map generated by build-icons.mjs).
import MAP from "./icon-map.js";

const baseName = (p) => String(p || "").replace(/\\/g, "/").replace(/\/+$/, "").split("/").pop();
function fileIconId(name) {
  const b = baseName(name), low = b.toLowerCase();
  if (MAP.fileNames[b]) return MAP.fileNames[b];
  if (MAP.fileNames[low]) return MAP.fileNames[low];
  // longest extension first: a.test.ts -> "test.ts", then "ts"
  let i = low.indexOf(".");
  while (i >= 0 && i < low.length - 1) {
    const ext = low.slice(i + 1);
    if (MAP.fileExtensions[ext]) return MAP.fileExtensions[ext];
    i = low.indexOf(".", i + 1);
  }
  return MAP.file;
}
function folderIconId(name, open, root) {
  const b = baseName(name), low = b.toLowerCase();
  const tbl = open ? MAP.folderNamesExpanded : MAP.folderNames;
  const hit = tbl[b] || tbl[low];
  if (hit) return hit;
  if (root) return open ? MAP.rootFolderOpen : MAP.rootFolder;
  return open ? MAP.folderOpen : MAP.folder;
}
// iconId(kind, name, {open, root}) -> id. iconPath(modName, id) -> appHome-relative path for image().
const iconId = (isDir, name, o = {}) => (isDir ? folderIconId(name, !!o.open, !!o.root) : fileIconId(name));
const iconPath = (modName, id) => {
  if (!/^[A-Za-z0-9_-]+$/.test(String(modName))) throw new Error("bad mod name");
  return `mods/${modName}/icons/${/^[A-Za-z0-9_.-]+$/.test(id) ? id : "file"}.svg`;
};
const resolveIcon = (modName, isDir, name, o) => iconPath(modName, iconId(isDir, name, o));
export { fileIconId, folderIconId, iconId, iconPath, resolveIcon };
